-- Platform metadata v1, PostgreSQL 15+. Apply once with a migration-owner role.
-- Runtime access is through the explicitly authorized, scoped Metadata adapter.
-- No extensions, credentials, source payloads or external services are created.
BEGIN;
CREATE SCHEMA platform;
CREATE TABLE platform.migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO platform.migrations(version) VALUES(1);
CREATE TABLE platform.workspaces(id uuid PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,settings jsonb NOT NULL DEFAULT '{}',quotas jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE platform.principals(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('user','service_account','agent')),identity_ref text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')));
CREATE TABLE platform.memberships(workspace_id uuid NOT NULL REFERENCES platform.workspaces(id),principal_id uuid NOT NULL REFERENCES platform.principals(id),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),PRIMARY KEY(workspace_id,principal_id));
CREATE TABLE platform.projects(workspace_id uuid NOT NULL REFERENCES platform.workspaces(id),id uuid NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE platform.grants(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL,project_id uuid,principal_id uuid NOT NULL,permission text NOT NULL CHECK(permission IN ('view','configure','execute','publish','administer','secret-use')),FOREIGN KEY(workspace_id,principal_id) REFERENCES platform.memberships,FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects,UNIQUE NULLS NOT DISTINCT(workspace_id,project_id,principal_id,permission));
CREATE TABLE platform.roles(workspace_id uuid NOT NULL REFERENCES platform.workspaces,id uuid NOT NULL,key text NOT NULL,name text NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,key));
CREATE TABLE platform.role_permissions(workspace_id uuid NOT NULL,role_id uuid NOT NULL,permission text NOT NULL CHECK(permission IN ('view','configure','execute','publish','administer','secret-use')),PRIMARY KEY(workspace_id,role_id,permission),FOREIGN KEY(workspace_id,role_id) REFERENCES platform.roles);
CREATE TABLE platform.role_bindings(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,project_id uuid,principal_id uuid NOT NULL,role_id uuid NOT NULL,FOREIGN KEY(workspace_id,principal_id) REFERENCES platform.memberships,FOREIGN KEY(workspace_id,role_id) REFERENCES platform.roles,FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects,UNIQUE NULLS NOT DISTINCT(workspace_id,project_id,principal_id,role_id));

-- Versioned processing and contract registries. Identity always pins a digest.
CREATE TABLE platform.contracts(workspace_id uuid NOT NULL REFERENCES platform.workspaces,key text NOT NULL,version integer NOT NULL CHECK(version>0),digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),kind text NOT NULL,schema_body jsonb NOT NULL,semantics jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,key,version),UNIQUE(workspace_id,key,version,digest));
CREATE TABLE platform.adapters(workspace_id uuid NOT NULL REFERENCES platform.workspaces,key text NOT NULL,version integer NOT NULL CHECK(version>0),digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),runtime text NOT NULL,artifact_uri text NOT NULL,artifact_digest text NOT NULL CHECK(artifact_digest~'^[a-f0-9]{64}$'),runtime_contract integer NOT NULL DEFAULT 1 CHECK(runtime_contract>0),capabilities jsonb NOT NULL,isolation jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),UNIQUE(workspace_id,key,version,digest));
CREATE TABLE platform.step_types(workspace_id uuid NOT NULL REFERENCES platform.workspaces,key text NOT NULL,version integer NOT NULL CHECK(version>0),digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),adapter_key text NOT NULL,adapter_version integer NOT NULL,category text NOT NULL,configuration_schema jsonb NOT NULL,input_ports jsonb NOT NULL,output_ports jsonb NOT NULL,bindings jsonb NOT NULL DEFAULT '{}',capabilities jsonb NOT NULL DEFAULT '[]',modes text[] NOT NULL CHECK(cardinality(modes)>0),PRIMARY KEY(workspace_id,key,version),UNIQUE(workspace_id,key,version,digest),FOREIGN KEY(workspace_id,adapter_key,adapter_version) REFERENCES platform.adapters);
CREATE TABLE platform.connector_types(workspace_id uuid NOT NULL REFERENCES platform.workspaces,key text NOT NULL,version integer NOT NULL CHECK(version>0),digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),kind text NOT NULL,configuration_schema jsonb NOT NULL,operations text[] NOT NULL,authentication text[] NOT NULL,capabilities jsonb NOT NULL,adapter_key text NOT NULL,adapter_version integer NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,adapter_key,adapter_version) REFERENCES platform.adapters);
CREATE TABLE platform.credentials(workspace_id uuid NOT NULL REFERENCES platform.workspaces,id uuid NOT NULL,provider text NOT NULL,secret_ref text NOT NULL,access_policy jsonb NOT NULL,rotation jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,id));
CREATE TABLE platform.connections(workspace_id uuid NOT NULL REFERENCES platform.workspaces,id uuid NOT NULL,connector_key text NOT NULL,connector_version integer NOT NULL,name text NOT NULL,configuration jsonb NOT NULL,credential_id uuid,status text NOT NULL CHECK(status IN ('active','disabled')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,connector_key,connector_version) REFERENCES platform.connector_types,FOREIGN KEY(workspace_id,credential_id) REFERENCES platform.credentials);
CREATE TABLE platform.resources(workspace_id uuid NOT NULL,project_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL CHECK(version>0),digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),kind text NOT NULL CHECK(kind IN ('source','destination','schema','model','deployment','model_config','prompt','inference','transform','filter','rule','taxonomy','validation','dataset','artifact','connection')),name text NOT NULL,PRIMARY KEY(workspace_id,key,version),UNIQUE(workspace_id,key,version,digest),UNIQUE(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects);
CREATE TABLE platform.resource_grants(workspace_id uuid NOT NULL,project_id uuid NOT NULL,resource_key text NOT NULL,resource_version integer NOT NULL,permission text NOT NULL CHECK(permission IN ('view','execute','secret-use')),PRIMARY KEY(workspace_id,project_id,resource_key,resource_version,permission),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects,FOREIGN KEY(workspace_id,resource_key,resource_version) REFERENCES platform.resources);
CREATE TABLE platform.sources(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'source' CHECK(kind='source'),connection_id uuid NOT NULL,locator text NOT NULL,source_kind text NOT NULL,discovery jsonb NOT NULL DEFAULT '{}',change_strategy jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,connection_id) REFERENCES platform.connections);
CREATE TABLE platform.destinations(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'destination' CHECK(kind='destination'),connection_id uuid NOT NULL,locator text NOT NULL,write_capabilities text[] NOT NULL,write_policy jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,connection_id) REFERENCES platform.connections);
CREATE TABLE platform.schemas(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'schema' CHECK(kind='schema'),schema_type text NOT NULL,body jsonb NOT NULL,compatibility jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind));
CREATE TABLE platform.models(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'model' CHECK(kind='model'),provider text NOT NULL,model_key text NOT NULL,capabilities jsonb NOT NULL,modalities text[] NOT NULL,parameters jsonb NOT NULL,context_limits jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind));
CREATE TABLE platform.model_deployments(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'deployment' CHECK(kind='deployment'),model_key text NOT NULL,model_version integer NOT NULL,runtime text NOT NULL,endpoint_ref text NOT NULL,model_revision text NOT NULL,tokenizer_ref text,configuration jsonb NOT NULL,status text NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,model_key,model_version) REFERENCES platform.models);
CREATE TABLE platform.model_configurations(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'model_config' CHECK(kind='model_config'),deployment_key text NOT NULL,deployment_version integer NOT NULL,generation jsonb NOT NULL,reasoning jsonb NOT NULL DEFAULT '{}',decoding jsonb NOT NULL DEFAULT '{}',resources jsonb NOT NULL DEFAULT '{}',response_format jsonb NOT NULL,provider_parameters jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,deployment_key,deployment_version) REFERENCES platform.model_deployments);
CREATE TABLE platform.prompts(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'prompt' CHECK(kind='prompt'),template text NOT NULL,variables jsonb NOT NULL,contract_key text NOT NULL,contract_version integer NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,contract_key,contract_version) REFERENCES platform.contracts);
CREATE TABLE platform.logic(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL CHECK(kind IN ('transform','filter','rule')),language text NOT NULL,expression text NOT NULL,input_contract text NOT NULL,input_version integer NOT NULL,output_contract text,output_version integer,configuration jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,input_contract,input_version) REFERENCES platform.contracts,FOREIGN KEY(workspace_id,output_contract,output_version) REFERENCES platform.contracts,CHECK((output_contract IS NULL)=(output_version IS NULL)));
CREATE TABLE platform.taxonomies(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'taxonomy' CHECK(kind='taxonomy'),metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind));
CREATE TABLE platform.categories(workspace_id uuid NOT NULL,taxonomy_key text NOT NULL,taxonomy_version integer NOT NULL,key text NOT NULL,parent_key text,label text NOT NULL,description text NOT NULL DEFAULT '',attributes jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,taxonomy_key,taxonomy_version,key),FOREIGN KEY(workspace_id,taxonomy_key,taxonomy_version) REFERENCES platform.taxonomies,FOREIGN KEY(workspace_id,taxonomy_key,taxonomy_version,parent_key) REFERENCES platform.categories,CHECK(parent_key IS DISTINCT FROM key));
CREATE TABLE platform.validation_policies(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'validation' CHECK(kind='validation'),contract_key text NOT NULL,contract_version integer NOT NULL,assertions jsonb NOT NULL,failure_action text NOT NULL CHECK(failure_action IN ('reject','quarantine','pause','warn')),sampling jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,contract_key,contract_version) REFERENCES platform.contracts);
CREATE TABLE platform.inference_profiles(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'inference' CHECK(kind='inference'),model_key text NOT NULL,model_version integer NOT NULL,prompt_key text NOT NULL,prompt_version integer NOT NULL,validation_key text,validation_version integer,input_mapping jsonb NOT NULL,output_mapping jsonb NOT NULL,batching jsonb NOT NULL,context_policy jsonb NOT NULL,strategy text NOT NULL,cost_policy jsonb NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,model_key,model_version) REFERENCES platform.model_configurations,FOREIGN KEY(workspace_id,prompt_key,prompt_version) REFERENCES platform.prompts,FOREIGN KEY(workspace_id,validation_key,validation_version) REFERENCES platform.validation_policies,CHECK((validation_key IS NULL)=(validation_version IS NULL)));

-- A workflow version owns graph identifiers. Ports carry exact pinned contracts.
CREATE TABLE platform.workflows(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id text NOT NULL,name text NOT NULL,owner_id uuid NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),current_version uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects,FOREIGN KEY(workspace_id,owner_id) REFERENCES platform.memberships);
CREATE TABLE platform.workflow_versions(workspace_id uuid NOT NULL,project_id uuid NOT NULL,workflow_id text NOT NULL,id uuid NOT NULL,number integer NOT NULL CHECK(number>0),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','retired')),graph_schema integer NOT NULL DEFAULT 1 CHECK(graph_schema>0),definition_hash text NOT NULL CHECK(definition_hash~'^[a-f0-9]{64}$'),definition jsonb NOT NULL,compiled_release jsonb NOT NULL DEFAULT '{}',execution_policy jsonb NOT NULL CHECK(execution_policy<>'{}'),resource_policy jsonb NOT NULL CHECK(resource_policy<>'{}'),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),published_at timestamptz,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,workflow_id,id),UNIQUE(workspace_id,project_id,workflow_id,number),FOREIGN KEY(workspace_id,project_id,workflow_id) REFERENCES platform.workflows,FOREIGN KEY(workspace_id,created_by) REFERENCES platform.memberships,CHECK((status='draft')=(published_at IS NULL)));
ALTER TABLE platform.workflows ADD FOREIGN KEY(workspace_id,project_id,id,current_version) REFERENCES platform.workflow_versions(workspace_id,project_id,workflow_id,id);
CREATE TABLE platform.stages(workspace_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,key text NOT NULL,name text NOT NULL,kind text NOT NULL DEFAULT 'group',execution_policy jsonb NOT NULL DEFAULT '{}',error_policy jsonb NOT NULL DEFAULT '{}',resource_policy jsonb NOT NULL DEFAULT '{}',display_order integer NOT NULL DEFAULT 0,PRIMARY KEY(workspace_id,project_id,version_id,key),FOREIGN KEY(workspace_id,project_id,version_id) REFERENCES platform.workflow_versions);
CREATE TABLE platform.steps(workspace_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,key text NOT NULL,stage_key text NOT NULL,type_key text NOT NULL,type_version integer NOT NULL,type_digest text NOT NULL,configuration jsonb NOT NULL,retry_policy jsonb NOT NULL DEFAULT '{}',timeout_policy jsonb NOT NULL DEFAULT '{}',resource_policy jsonb NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT true,PRIMARY KEY(workspace_id,project_id,version_id,key),FOREIGN KEY(workspace_id,project_id,version_id,stage_key) REFERENCES platform.stages,FOREIGN KEY(workspace_id,type_key,type_version,type_digest) REFERENCES platform.step_types(workspace_id,key,version,digest));
CREATE TABLE platform.ports(workspace_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,step_key text NOT NULL,key text NOT NULL,direction text NOT NULL CHECK(direction IN ('input','output')),contract_key text NOT NULL,contract_version integer NOT NULL,contract_digest text NOT NULL,required boolean NOT NULL DEFAULT true,cardinality text NOT NULL DEFAULT 'one' CHECK(cardinality IN ('one','many')),accepts_stream boolean NOT NULL DEFAULT false,PRIMARY KEY(workspace_id,project_id,version_id,step_key,key,direction),FOREIGN KEY(workspace_id,project_id,version_id,step_key) REFERENCES platform.steps,FOREIGN KEY(workspace_id,contract_key,contract_version,contract_digest) REFERENCES platform.contracts(workspace_id,key,version,digest));
CREATE TABLE platform.edges(workspace_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,key text NOT NULL,source_step text NOT NULL,source_port text NOT NULL,source_direction text NOT NULL DEFAULT 'output' CHECK(source_direction='output'),target_step text NOT NULL,target_port text NOT NULL,target_direction text NOT NULL DEFAULT 'input' CHECK(target_direction='input'),routing_key text,routing_version integer,transfer_policy jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,project_id,version_id,key),UNIQUE(workspace_id,project_id,version_id,source_step,source_port,target_step,target_port),FOREIGN KEY(workspace_id,project_id,version_id,source_step,source_port,source_direction) REFERENCES platform.ports,FOREIGN KEY(workspace_id,project_id,version_id,target_step,target_port,target_direction) REFERENCES platform.ports,FOREIGN KEY(workspace_id,routing_key,routing_version) REFERENCES platform.logic,CHECK(source_step<>target_step),CHECK((routing_key IS NULL)=(routing_version IS NULL)));
CREATE TABLE platform.step_resources(workspace_id uuid NOT NULL,project_id uuid NOT NULL,version_id uuid NOT NULL,step_key text NOT NULL,role text NOT NULL,resource_key text NOT NULL,resource_version integer NOT NULL,resource_digest text NOT NULL,PRIMARY KEY(workspace_id,project_id,version_id,step_key,role),FOREIGN KEY(workspace_id,project_id,version_id,step_key) REFERENCES platform.steps,FOREIGN KEY(workspace_id,resource_key,resource_version,resource_digest) REFERENCES platform.resources(workspace_id,key,version,digest));
CREATE TABLE platform.triggers(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,workflow_id text NOT NULL,kind text NOT NULL,configuration jsonb NOT NULL,enabled boolean NOT NULL DEFAULT false,concurrency_policy jsonb NOT NULL,PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,workflow_id) REFERENCES platform.workflows);

-- Logical data snapshots and physical objects have distinct lifecycles.
CREATE TABLE platform.datasets(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,key text NOT NULL,name text NOT NULL,kind text NOT NULL,identity_strategy jsonb NOT NULL,retention_policy jsonb NOT NULL DEFAULT '{}',classification text NOT NULL DEFAULT 'unclassified',PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,key),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects);
CREATE TABLE platform.dataset_versions(workspace_id uuid NOT NULL,project_id uuid NOT NULL,dataset_id uuid NOT NULL,id uuid NOT NULL,number integer NOT NULL CHECK(number>0),schema_key text,schema_version integer,content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),manifest_uri text NOT NULL,record_count bigint NOT NULL CHECK(record_count>=0),byte_count bigint NOT NULL CHECK(byte_count>=0),statistics jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'staging' CHECK(state IN ('staging','published','retired')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,dataset_id,id),UNIQUE(workspace_id,project_id,dataset_id,number),FOREIGN KEY(workspace_id,project_id,dataset_id) REFERENCES platform.datasets,FOREIGN KEY(workspace_id,schema_key,schema_version) REFERENCES platform.schemas,CHECK((schema_key IS NULL)=(schema_version IS NULL)));
CREATE TABLE platform.dataset_parents(workspace_id uuid NOT NULL,project_id uuid NOT NULL,dataset_id uuid NOT NULL,revision_id uuid NOT NULL,parent_id uuid NOT NULL,PRIMARY KEY(workspace_id,project_id,revision_id,parent_id),FOREIGN KEY(workspace_id,project_id,dataset_id,revision_id) REFERENCES platform.dataset_versions(workspace_id,project_id,dataset_id,id),FOREIGN KEY(workspace_id,project_id,dataset_id,parent_id) REFERENCES platform.dataset_versions(workspace_id,project_id,dataset_id,id),CHECK(revision_id<>parent_id));
CREATE TABLE platform.representations(workspace_id uuid NOT NULL,project_id uuid NOT NULL,revision_id uuid NOT NULL,id uuid NOT NULL,format text NOT NULL,format_version text NOT NULL,encoding jsonb NOT NULL DEFAULT '{}',schema_mapping jsonb NOT NULL DEFAULT '{}',layout jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'staging' CHECK(state IN ('staging','published')),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,revision_id) REFERENCES platform.dataset_versions);
CREATE TABLE platform.record_identities(workspace_id uuid NOT NULL,project_id uuid NOT NULL,dataset_id uuid NOT NULL,key text NOT NULL,algorithm text NOT NULL,source_ref text NOT NULL,first_observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,dataset_id,key),FOREIGN KEY(workspace_id,project_id,dataset_id) REFERENCES platform.datasets);
CREATE TABLE platform.record_revisions(workspace_id uuid NOT NULL,project_id uuid NOT NULL,dataset_id uuid NOT NULL,revision_id uuid NOT NULL,key text NOT NULL,content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),lineage_uri text NOT NULL,event_time timestamptz,ingested_at timestamptz NOT NULL DEFAULT clock_timestamp(),validity jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,project_id,revision_id,key),FOREIGN KEY(workspace_id,project_id,dataset_id,key) REFERENCES platform.record_identities,FOREIGN KEY(workspace_id,project_id,dataset_id,revision_id) REFERENCES platform.dataset_versions(workspace_id,project_id,dataset_id,id));

CREATE TABLE platform.runs(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,workflow_id text NOT NULL,version_id uuid NOT NULL,trigger_id uuid,mode text NOT NULL CHECK(mode IN ('batch','incremental','streaming','windowed','scheduled','event','manual','replay','dry-run')),status text NOT NULL DEFAULT 'running' CHECK(status IN ('queued','running','paused','completed','failed','cancelled')),parameters jsonb NOT NULL DEFAULT '{}',configuration_hash text NOT NULL CHECK(configuration_hash~'^[a-f0-9]{64}$'),initiated_by uuid NOT NULL,started_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,id,version_id),FOREIGN KEY(workspace_id,project_id,workflow_id,version_id) REFERENCES platform.workflow_versions(workspace_id,project_id,workflow_id,id),FOREIGN KEY(workspace_id,project_id,trigger_id) REFERENCES platform.triggers,FOREIGN KEY(workspace_id,initiated_by) REFERENCES platform.memberships);
CREATE TABLE platform.stage_runs(workspace_id uuid NOT NULL,project_id uuid NOT NULL,run_id uuid NOT NULL,version_id uuid NOT NULL,id uuid NOT NULL,stage_key text NOT NULL,status text NOT NULL DEFAULT 'queued',started_at timestamptz,completed_at timestamptz,statistics jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,run_id,version_id,stage_key),FOREIGN KEY(workspace_id,project_id,run_id,version_id) REFERENCES platform.runs(workspace_id,project_id,id,version_id),FOREIGN KEY(workspace_id,project_id,version_id,stage_key) REFERENCES platform.stages);
CREATE TABLE platform.step_runs(workspace_id uuid NOT NULL,project_id uuid NOT NULL,run_id uuid NOT NULL,version_id uuid NOT NULL,id uuid NOT NULL,stage_key text NOT NULL,step_key text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','cancelled')),tasks_closed boolean NOT NULL DEFAULT false,configuration_hash text NOT NULL CHECK(configuration_hash~'^[a-f0-9]{64}$'),started_at timestamptz,completed_at timestamptz,statistics jsonb NOT NULL DEFAULT '{}',error_summary text,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,id,run_id),UNIQUE(workspace_id,project_id,run_id,step_key),UNIQUE(workspace_id,project_id,id,version_id,step_key),FOREIGN KEY(workspace_id,project_id,run_id,version_id) REFERENCES platform.runs(workspace_id,project_id,id,version_id),FOREIGN KEY(workspace_id,project_id,run_id,version_id,stage_key) REFERENCES platform.stage_runs(workspace_id,project_id,run_id,version_id,stage_key),FOREIGN KEY(workspace_id,project_id,version_id,step_key) REFERENCES platform.steps);
CREATE TABLE platform.tasks(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,step_run_id uuid NOT NULL,key text NOT NULL,partition_key text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','leased','completed','failed','cancelled')),ready_at timestamptz NOT NULL DEFAULT clock_timestamp(),fence bigint NOT NULL DEFAULT 0 CHECK(fence>=0),max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 100),lease_owner text,lease_actor uuid,lease_token uuid,lease_expires_at timestamptz,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,step_run_id,key),FOREIGN KEY(workspace_id,project_id,step_run_id,run_id) REFERENCES platform.step_runs(workspace_id,project_id,id,run_id),FOREIGN KEY(workspace_id,lease_actor) REFERENCES platform.memberships,CHECK((status='leased')=(lease_owner IS NOT NULL AND lease_actor IS NOT NULL AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL)));
CREATE INDEX task_ready ON platform.tasks(workspace_id,project_id,status,ready_at,lease_expires_at);
CREATE TABLE platform.attempts(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,task_id uuid NOT NULL,fence bigint NOT NULL CHECK(fence>0),worker text NOT NULL,actor uuid NOT NULL,status text NOT NULL CHECK(status IN ('running','completed','failed','expired')),started_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,error_code text,error_details jsonb,resources jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,task_id,fence),UNIQUE(workspace_id,project_id,task_id,id,fence),FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES platform.tasks,FOREIGN KEY(workspace_id,actor) REFERENCES platform.memberships);
CREATE TABLE platform.commits(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,task_id uuid NOT NULL,attempt_id uuid NOT NULL,fence bigint NOT NULL,key text NOT NULL,digest text NOT NULL CHECK(digest~'^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,task_id),FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES platform.tasks,FOREIGN KEY(workspace_id,project_id,task_id,attempt_id,fence) REFERENCES platform.attempts(workspace_id,project_id,task_id,id,fence));
CREATE TABLE platform.artifacts(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,representation_id uuid NOT NULL,commit_id uuid NOT NULL,step_run_id uuid NOT NULL,backend text NOT NULL DEFAULT 'local',uri text NOT NULL,media_type text NOT NULL,bytes bigint NOT NULL CHECK(bytes>=0),checksum text NOT NULL CHECK(checksum~'^[a-f0-9]{64}$'),checksum_algorithm text NOT NULL DEFAULT 'sha256' CHECK(checksum_algorithm='sha256'),partition_key text NOT NULL DEFAULT '',metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),retention_until timestamptz,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,backend,uri),FOREIGN KEY(workspace_id,project_id,representation_id) REFERENCES platform.representations,FOREIGN KEY(workspace_id,project_id,commit_id) REFERENCES platform.commits,FOREIGN KEY(workspace_id,project_id,step_run_id) REFERENCES platform.step_runs);
CREATE TABLE platform.dataset_resources(workspace_id uuid NOT NULL,project_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'dataset' CHECK(kind='dataset'),revision_id uuid NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,project_id,revision_id) REFERENCES platform.dataset_versions);
CREATE TABLE platform.artifact_resources(workspace_id uuid NOT NULL,project_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'artifact' CHECK(kind='artifact'),artifact_id uuid NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,project_id,artifact_id) REFERENCES platform.artifacts);
CREATE TABLE platform.connection_resources(workspace_id uuid NOT NULL,key text NOT NULL,version integer NOT NULL,kind text NOT NULL DEFAULT 'connection' CHECK(kind='connection'),connection_id uuid NOT NULL,PRIMARY KEY(workspace_id,key,version),FOREIGN KEY(workspace_id,key,version,kind) REFERENCES platform.resources(workspace_id,key,version,kind),FOREIGN KEY(workspace_id,connection_id) REFERENCES platform.connections);
CREATE TABLE platform.bindings(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,step_run_id uuid NOT NULL,version_id uuid NOT NULL,step_key text NOT NULL,port_key text NOT NULL,direction text NOT NULL CHECK(direction IN ('input','output')),artifact_id uuid NOT NULL,partition_key text NOT NULL DEFAULT '',PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,step_run_id,port_key,direction,artifact_id),FOREIGN KEY(workspace_id,project_id,step_run_id,version_id,step_key) REFERENCES platform.step_runs(workspace_id,project_id,id,version_id,step_key),FOREIGN KEY(workspace_id,project_id,version_id,step_key,port_key,direction) REFERENCES platform.ports,FOREIGN KEY(workspace_id,project_id,artifact_id) REFERENCES platform.artifacts);
CREATE TABLE platform.checkpoints(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,step_run_id uuid NOT NULL,task_id uuid NOT NULL,commit_id uuid NOT NULL,partition_key text NOT NULL,cursor_state jsonb NOT NULL,state_artifact uuid,committed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,task_id),FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES platform.tasks,FOREIGN KEY(workspace_id,project_id,step_run_id,run_id) REFERENCES platform.step_runs(workspace_id,project_id,id,run_id),FOREIGN KEY(workspace_id,project_id,commit_id) REFERENCES platform.commits,FOREIGN KEY(workspace_id,project_id,state_artifact) REFERENCES platform.artifacts);
CREATE TABLE platform.execution_events(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id bigint GENERATED ALWAYS AS IDENTITY,run_id uuid NOT NULL,entity_kind text NOT NULL,entity_id text NOT NULL,type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',trace_id text,correlation_id text,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,run_id) REFERENCES platform.runs);
CREATE INDEX event_run ON platform.execution_events(workspace_id,project_id,run_id,id);
CREATE TABLE platform.lineage(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,step_run_id uuid NOT NULL,source_artifact uuid NOT NULL,target_artifact uuid NOT NULL,kind text NOT NULL,manifest_uri text,transformation_ref text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,step_run_id,run_id) REFERENCES platform.step_runs(workspace_id,project_id,id,run_id),FOREIGN KEY(workspace_id,project_id,source_artifact) REFERENCES platform.artifacts,FOREIGN KEY(workspace_id,project_id,target_artifact) REFERENCES platform.artifacts,CHECK(source_artifact<>target_artifact));
CREATE TABLE platform.semantic_entities(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,type text NOT NULL,canonical_key text NOT NULL,attributes jsonb NOT NULL,confidence numeric CHECK(confidence BETWEEN 0 AND 1),resolution text NOT NULL,PRIMARY KEY(workspace_id,project_id,id),UNIQUE(workspace_id,project_id,type,canonical_key),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects);
CREATE TABLE platform.semantic_relationships(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,source_id uuid NOT NULL,target_id uuid NOT NULL,type text NOT NULL,confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence jsonb NOT NULL,step_run_id uuid NOT NULL,valid_from timestamptz NOT NULL DEFAULT clock_timestamp(),valid_to timestamptz,PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,source_id) REFERENCES platform.semantic_entities,FOREIGN KEY(workspace_id,project_id,target_id) REFERENCES platform.semantic_entities,FOREIGN KEY(workspace_id,project_id,step_run_id) REFERENCES platform.step_runs,CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE platform.assertions(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,step_run_id uuid NOT NULL,subject_id uuid NOT NULL,predicate text NOT NULL,value jsonb NOT NULL,deployment_key text NOT NULL,deployment_version integer NOT NULL,profile_key text NOT NULL,profile_version integer NOT NULL,confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence jsonb NOT NULL CHECK(jsonb_typeof(evidence)='array' AND jsonb_array_length(evidence)>0),validation_status text NOT NULL CHECK(validation_status IN ('unvalidated','accepted','rejected')),produced_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,subject_id) REFERENCES platform.semantic_entities,FOREIGN KEY(workspace_id,project_id,step_run_id) REFERENCES platform.step_runs,FOREIGN KEY(workspace_id,deployment_key,deployment_version) REFERENCES platform.model_deployments,FOREIGN KEY(workspace_id,profile_key,profile_version) REFERENCES platform.inference_profiles);
CREATE TABLE platform.quality_results(workspace_id uuid NOT NULL,project_id uuid NOT NULL,step_run_id uuid NOT NULL,key text NOT NULL,policy_key text,policy_version integer,blocking boolean NOT NULL,passed boolean NOT NULL,observed jsonb NOT NULL,expected jsonb NOT NULL,sample_uri text,PRIMARY KEY(workspace_id,project_id,step_run_id,key),FOREIGN KEY(workspace_id,project_id,step_run_id) REFERENCES platform.step_runs,FOREIGN KEY(workspace_id,policy_key,policy_version) REFERENCES platform.validation_policies,CHECK((policy_key IS NULL)=(policy_version IS NULL)));
CREATE TABLE platform.metrics(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id bigint GENERATED ALWAYS AS IDENTITY,run_id uuid NOT NULL,name text NOT NULL,value numeric NOT NULL,unit text NOT NULL,dimensions jsonb NOT NULL DEFAULT '{}',observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,run_id) REFERENCES platform.runs);
CREATE TABLE platform.usage(workspace_id uuid NOT NULL,project_id uuid NOT NULL,id uuid NOT NULL,attempt_id uuid NOT NULL,resource text NOT NULL,quantity numeric NOT NULL CHECK(quantity>=0),unit text NOT NULL,estimated_cost numeric CHECK(estimated_cost>=0),actual_cost numeric CHECK(actual_cost>=0),currency text,pricing_version text,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,attempt_id) REFERENCES platform.attempts,CHECK(actual_cost IS NULL OR (currency IS NOT NULL AND pricing_version IS NOT NULL)));
CREATE TABLE platform.audit(workspace_id uuid NOT NULL,project_id uuid NOT NULL,sequence bigint GENERATED ALWAYS AS IDENTITY,actor_id uuid NOT NULL,action text NOT NULL,target_type text NOT NULL,target_id text NOT NULL,summary jsonb NOT NULL,previous_hash text NOT NULL,event_hash text NOT NULL CHECK(event_hash~'^[a-f0-9]{64}$'),correlation_id text,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,project_id,sequence),FOREIGN KEY(workspace_id,project_id) REFERENCES platform.projects,FOREIGN KEY(workspace_id,actor_id) REFERENCES platform.memberships);
CREATE INDEX audit_scope ON platform.audit(workspace_id,project_id,sequence DESC);

-- Append-only records and immutable registry versions cannot be rewritten.
CREATE FUNCTION platform.immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable % record',TG_TABLE_NAME; END $$;
DO $$ DECLARE name text; BEGIN FOREACH name IN ARRAY ARRAY['contracts','adapters','step_types','connector_types','credentials','connections','dataset_resources','artifact_resources','connection_resources','resources','sources','destinations','schemas','models','model_deployments','model_configurations','prompts','logic','taxonomies','categories','validation_policies','inference_profiles','artifacts','commits','checkpoints','bindings','lineage','assertions','semantic_relationships','execution_events','usage','metrics','audit'] LOOP EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON platform.%I FOR EACH ROW EXECUTE FUNCTION platform.immutable()',name); END LOOP; END $$;
CREATE FUNCTION platform.guard_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' AND OLD.status<>'draft' THEN RAISE EXCEPTION 'published workflow is immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'draft' THEN
  IF NOT (OLD.status='published' AND NEW.status='retired' AND (to_jsonb(OLD)-'status')=(to_jsonb(NEW)-'status')) THEN RAISE EXCEPTION 'published workflow is immutable'; END IF;
 END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER version_immutable BEFORE UPDATE OR DELETE ON platform.workflow_versions FOR EACH ROW EXECUTE FUNCTION platform.guard_version();
CREATE FUNCTION platform.guard_graph() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE current_status text; BEGIN
 IF TG_OP<>'INSERT' THEN SELECT status INTO current_status FROM platform.workflow_versions WHERE workspace_id=OLD.workspace_id AND project_id=OLD.project_id AND id=OLD.version_id FOR SHARE; IF current_status<>'draft' THEN RAISE EXCEPTION 'published graph is immutable'; END IF; END IF;
 IF TG_OP<>'DELETE' THEN SELECT status INTO current_status FROM platform.workflow_versions WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id AND id=NEW.version_id FOR SHARE; IF current_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'published graph is immutable or missing'; END IF; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
DO $$ DECLARE name text; BEGIN FOREACH name IN ARRAY ARRAY['stages','steps','ports','edges','step_resources'] LOOP EXECUTE format('CREATE TRIGGER graph_immutable BEFORE INSERT OR UPDATE OR DELETE ON platform.%I FOR EACH ROW EXECUTE FUNCTION platform.guard_graph()',name); END LOOP; END $$;
CREATE FUNCTION platform.check_publication() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status='draft') THEN
  IF TG_OP='INSERT' THEN RAISE EXCEPTION 'create a draft before publication'; END IF;
  IF NOT EXISTS(SELECT 1 FROM platform.steps WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id AND version_id=NEW.id AND enabled) THEN RAISE EXCEPTION 'workflow has no enabled steps'; END IF;
  IF EXISTS(SELECT 1 FROM platform.edges e JOIN platform.steps a ON (a.workspace_id,a.project_id,a.version_id,a.key)=(e.workspace_id,e.project_id,e.version_id,e.source_step) JOIN platform.steps b ON (b.workspace_id,b.project_id,b.version_id,b.key)=(e.workspace_id,e.project_id,e.version_id,e.target_step) WHERE e.workspace_id=NEW.workspace_id AND e.project_id=NEW.project_id AND e.version_id=NEW.id AND (NOT a.enabled OR NOT b.enabled)) THEN RAISE EXCEPTION 'edge references a disabled step'; END IF;
  IF EXISTS(SELECT 1 FROM platform.ports p WHERE p.workspace_id=NEW.workspace_id AND p.project_id=NEW.project_id AND p.version_id=NEW.id AND p.direction='input' AND p.required AND NOT EXISTS(SELECT 1 FROM platform.edges e WHERE e.workspace_id=p.workspace_id AND e.project_id=p.project_id AND e.version_id=p.version_id AND e.target_step=p.step_key AND e.target_port=p.key)) THEN RAISE EXCEPTION 'required input has no edge'; END IF;
  IF EXISTS(SELECT 1 FROM platform.edges e JOIN platform.ports a ON (a.workspace_id,a.project_id,a.version_id,a.step_key,a.key,a.direction)=(e.workspace_id,e.project_id,e.version_id,e.source_step,e.source_port,'output') JOIN platform.ports b ON (b.workspace_id,b.project_id,b.version_id,b.step_key,b.key,b.direction)=(e.workspace_id,e.project_id,e.version_id,e.target_step,e.target_port,'input') WHERE e.workspace_id=NEW.workspace_id AND e.project_id=NEW.project_id AND e.version_id=NEW.id AND (a.contract_key,a.contract_version,a.contract_digest) IS DISTINCT FROM (b.contract_key,b.contract_version,b.contract_digest)) THEN RAISE EXCEPTION 'port contracts are incompatible'; END IF;
  IF EXISTS(SELECT 1 FROM platform.edges e JOIN platform.ports p ON (p.workspace_id,p.project_id,p.version_id,p.step_key,p.key,p.direction)=(e.workspace_id,e.project_id,e.version_id,e.target_step,e.target_port,'input') WHERE e.workspace_id=NEW.workspace_id AND e.project_id=NEW.project_id AND e.version_id=NEW.id AND p.cardinality='one' GROUP BY e.target_step,e.target_port HAVING count(*)>1) THEN RAISE EXCEPTION 'single input has multiple edges'; END IF;
  IF EXISTS(WITH RECURSIVE walk(origin,target) AS (SELECT source_step,target_step FROM platform.edges WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id AND version_id=NEW.id UNION SELECT w.origin,e.target_step FROM walk w JOIN platform.edges e ON e.source_step=w.target AND e.workspace_id=NEW.workspace_id AND e.project_id=NEW.project_id AND e.version_id=NEW.id) SELECT 1 FROM walk WHERE origin=target) THEN RAISE EXCEPTION 'workflow cycle requires an explicit bounded-loop adapter'; END IF;
  IF EXISTS(SELECT 1 FROM platform.step_resources s JOIN platform.resources r ON (r.workspace_id,r.key,r.version)=(s.workspace_id,s.resource_key,s.resource_version) WHERE s.workspace_id=NEW.workspace_id AND s.project_id=NEW.project_id AND s.version_id=NEW.id AND r.project_id<>NEW.project_id AND NOT EXISTS(SELECT 1 FROM platform.resource_grants g WHERE g.workspace_id=s.workspace_id AND g.project_id=s.project_id AND g.resource_key=s.resource_key AND g.resource_version=s.resource_version AND g.permission='view')) THEN RAISE EXCEPTION 'resource reference is unauthorized'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER publication_valid BEFORE INSERT OR UPDATE OF status ON platform.workflow_versions FOR EACH ROW EXECUTE FUNCTION platform.check_publication();
CREATE FUNCTION platform.check_run() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM platform.workflow_versions WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id AND id=NEW.version_id AND workflow_id=NEW.workflow_id AND status='published') THEN RAISE EXCEPTION 'run requires a published workflow'; END IF; RETURN NEW; END $$;
CREATE TRIGGER run_published BEFORE INSERT ON platform.runs FOR EACH ROW EXECUTE FUNCTION platform.check_run();
CREATE FUNCTION platform.guard_dataset() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state<>'staging' THEN RAISE EXCEPTION 'published dataset revision is immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER dataset_immutable BEFORE UPDATE OR DELETE ON platform.dataset_versions FOR EACH ROW EXECUTE FUNCTION platform.guard_dataset();
CREATE FUNCTION platform.guard_representation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='published' THEN RAISE EXCEPTION 'published representation is immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER representation_immutable BEFORE UPDATE OR DELETE ON platform.representations FOR EACH ROW EXECUTE FUNCTION platform.guard_representation();
-- Do not grant runtime principals raw table mutation rights. The trusted API
-- service uses explicit permission checks; migration/observability owners remain separate.
REVOKE ALL ON ALL TABLES IN SCHEMA platform FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA platform FROM PUBLIC;
COMMIT;
